  Box, Card, Dashboard, LocalChoice, LocalValue, Panel, Row, Shell,
  createNode, fetchValue, preload, record, resolveName, submit, withRenderer,
} from './widgets';
type PageProps = Record<string, any>;
type RowData = { id: string; name: string; [key: string]: unknown };

export class Page extends React.Component<PageProps> {
      #ready = true;
      fallback = <p>Class field fallback {this.props.count}</p>;
      get preview() { return <aside>Class getter preview {this.props.mode}</aside>; }
      render() {
        const props = this.props;
        const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
        return <Shell ready={this.#ready} fallback={this.fallback} preview={this.preview}><main><Card children={(slots.header = <h2>Assigned header {<Fragment key={key}>Fragment <Derived context={context}>{resolveName()}</Derived> tail {count}</Fragment>}</h2>, <Fragment key={key}>Fragment <Derived context={context}>{resolveName()}</Derived> tail {count}</Fragment>)}
      fallback={(slots.footer ??= <aside>Assigned footer {<Fragment key={key}>Fragment <Derived context={context}>{resolveName()}</Derived> tail {count}</Fragment>}</aside>)}>
      {enabled && (slots.selected = <p>Selected {<Fragment key={key}>Fragment <Derived context={context}>{resolveName()}</Derived> tail {count}</Fragment>}</p>)}
      Final visible children {count}
    </Card><footer>After assignment {account.name}</footer></main></Shell>;
      }
    }

